// Prepare Domains: one item per sheet row that has a website. Rows without one are skipped and
// never written back. The registrable domain is read from the URL by pattern (n8n's Code sandbox
// has no URL class). A shared host (facebook.com, wixsite.com, ...) says nothing about the business
// on it, and an IP address has no registration, so those rows get "unknown" without a lookup.
const cfg = $('Settings').first().json;
for (const k of ['rdap_pace_seconds', 'max_retries']) {
  if (!(Number.isFinite(Number(cfg[k])) && Number(cfg[k]) >= 0)) throw new Error(`Settings: ${k} must be a number of 0 or more`);
}
const column = String(cfg.website_column || 'website').trim();

const PLATFORMS = ['facebook.com', 'fb.com', 'instagram.com', 'linkedin.com', 'twitter.com', 'x.com', 'tiktok.com',
  'youtube.com', 'linktr.ee', 'yelp.com', 'google.com', 'business.site', 'wixsite.com', 'wix.com',
  'squarespace.com', 'square.site', 'weebly.com', 'wordpress.com', 'blogspot.com', 'godaddysites.com',
  'myshopify.com', 'carrd.co', 'github.io', 'nextdoor.com', 'yellowpages.com', 'bbb.org', 'angi.com',
  'homeadvisor.com', 'thumbtack.com', 'houzz.com', 'vagaro.com', 'booksy.com', 'square.com',
  'toasttab.com', 'doordash.com', 'ubereats.com', 'grubhub.com', 'opentable.com', 'zocdoc.com',
  'healthgrades.com'];
const SECOND_LEVEL = new Set(['co', 'com', 'net', 'org', 'gov', 'ac', 'edu']); // shop.example.co.uk -> example.co.uk

const registrableDomain = (site) => {
  const authority = /^(?:[a-z][a-z0-9+.-]*:)?\/\/([^/?#]*)/i.exec(site.includes('//') ? site : `//${site}`);
  let host = (authority ? authority[1] : '').replace(/^.*@/, '').replace(/:\d*$/, '').toLowerCase().replace(/\.+$/, '');
  if (host.startsWith('www.')) host = host.slice(4);
  if (!host.includes('.') || host.startsWith('[') || /^[0-9.]+$/.test(host)) return { domain: null, why: 'no domain in website' };
  if (PLATFORMS.some((p) => host === p || host.endsWith(`.${p}`))) return { domain: null, why: 'shared host, not the business’s own domain' };
  const labels = host.split('.');
  const keep = labels.length >= 3 && labels[labels.length - 1].length === 2 && SECOND_LEVEL.has(labels[labels.length - 2]) ? 3 : 2;
  return { domain: labels.slice(-keep).join('.'), why: null };
};

const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: row } of $input.all()) {
  const website = String(row[column] ?? '').trim();
  if (!website || row.row_number == null) continue; // no website: skipped, nothing written back
  const { domain, why } = registrableDomain(website);
  const base = { row_number: row.row_number, website, domain, attempt: 0, requests: 0, retries: 0, wait_s: Number(cfg.rdap_pace_seconds), checked_at: today };
  out.push({ json: domain
    ? { ...base, lookup: 'yes' }
    : { ...base, lookup: 'no', domain_created: 'unknown', years_registered: 'unknown', age_source: why } });
}
return out;

// Collect Results: every row that went through the loop, reduced to the five columns the sheet
// node updates, matched on row_number. Nothing else on the row is touched.
const COLUMNS = ['row_number', 'domain_created', 'years_registered', 'age_source', 'checked_at'];
const rows = $input.all().map(({ json: s }) => ({ json: Object.fromEntries(COLUMNS.map((c) => [c, s[c]])) }));
const dated = rows.filter((r) => r.json.age_source === 'rdap').length;
console.log(`domain-age ${rows[0]?.json.checked_at ?? ''}: rows=${rows.length} dated=${dated} unknown=${rows.length - dated}`);
return rows;

// Check RDAP Response: rdap.org answered for the current row's domain (RFC 9083 JSON), or did not answer.
// 200 with a "registration" event: domain_created is that date, years_registered the full years since.
// 429 or 5xx, or no response at all (timeout, DNS, connection refused: the HTTP node continues on
// error and hands over an error item instead of a status): wait 1, 2, 4, 8, 16 s and ask again, up
// to max_retries; then "unknown", never a guess.
// 404 (not in RDAP) or a date that does not parse: "unknown", with the reason in age_source.
const cfg = $('Settings').first().json;
const state = $('Wait Before RDAP').first().json; // the row whose domain was just looked up
const res = $input.first().json;
const status = Number(res.statusCode);
const today = new Date().toISOString().slice(0, 10);
const base = { ...state, requests: state.requests + 1, checked_at: today };
const unknown = (why) => [{ json: { ...base, domain_created: 'unknown', years_registered: 'unknown', age_source: why, next: 'done' } }];

// A short reason for the sheet cell: the error's code or name and the first line of its message, never the
// stack, never braces or brackets (a JSON-shaped message stays out of the cell), never more than 120
// characters in all. Cuts fall between characters (code points), so an emoji is never split in half.
const clean = (s) => String(s).split('\n')[0].replace(/[{}[\]]/g, '');
const cut = (s, n) => [...s].slice(0, n).join('');
const errorText = (e) => {
  let out = 'unknown error';
  if (typeof e === 'string') out = clean(e);
  else if (e && typeof e === 'object') {
    const head = cut(clean(e.code || e.name || 'error'), 40);
    const msg = e.message ? clean(e.message) : '';
    out = msg ? `${head}: ${msg}` : head;
  }
  return cut(out, 120);
};

const retryable = [429, 500, 502, 503, 504].includes(status) || !Number.isFinite(status);
if (retryable) {
  const attempts = state.attempt + 1;
  if (state.attempt >= Number(cfg.max_retries)) {
    return unknown(Number.isFinite(status) ? `rdap answered HTTP ${status} ${attempts} times` : `rdap unreachable ${attempts} times (${errorText(res.error)})`);
  }
  return [{ json: { ...base, attempt: state.attempt + 1, retries: state.retries + 1, wait_s: 2 ** state.attempt, next: 'rdap' } }];
}
if (status === 404) return unknown('domain not found in RDAP');
if (status !== 200) return unknown(`rdap answered HTTP ${status}`);

const event = (res.body?.events ?? []).find((e) => e.eventAction === 'registration' && e.eventDate);
if (!event) return unknown('no registration event in the RDAP record');
const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(event.eventDate).trim()); // the date part, as written: no time-zone shift
const created = m && !Number.isNaN(Date.parse(m[1])) ? m[1] : null;
if (!created) return unknown('registration date unreadable');
const years = Math.floor((Date.parse(today) - Date.parse(created)) / 86400000 / 365.25);
if (years < 0) return unknown('registration date is in the future');
return [{ json: { ...base, domain_created: created, years_registered: years, age_source: 'rdap', next: 'done' } }];
